def transform(grid):
    h, w = len(grid), len(grid[0])

    # A solid divider separates two panels.
    for c in range(w):
        if len(set(grid[r][c] for r in range(h))) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if left and right and len(left[0]) == len(right[0]):
                from collections import Counter
                freq = Counter(v for row in right for v in row)
                background = freq.most_common(1)[0][0]
                return [[3 if v != background else 1 for v in row] for row in right]

    # Horizontal divider: mark positions that are background in both panels.
    for r in range(h):
        if len(set(grid[r])) == 1:
            top, bottom = grid[:r], grid[r + 1:]
            n = min(len(top), len(bottom))
            bg_top, bg_bottom = grid[0][0], grid[r + 1][0]
            return [[3 if top[i][j] == bg_top and bottom[i][j] == bg_bottom else 5
                     for j in range(w)] for i in range(n)]
